PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://example.org/ref#>
SELECT ?zone ?tz WHERE {
  ?zone rdfs:label "Perimeter_top_ZN_4" .
  ?tz ref:hasTimeseriesId ?ts .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER (contains(?label, "top_ZN_4"))
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?p ?label WHERE {
  ?zone rdfs:label "Perimeter_top_ZN_4" .
  ?zone brick:hasPoint ?p .
  ?p rdfs:label ?label .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?room ?p ?label ?ts WHERE {
  ?room a brick:Room .
  ?room rdfs:label ?rl .
  FILTER (contains(?rl, "top_ZN_4"))
  ?room brick:hasPoint ?p .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?ts }
}

